Method.Implementation:
		#dim status AS %Status=$$$OK
		$$$TRACE(" Inside CallOvertureServices()..........")

     $$$TRACE(" Target Operation: " _ process1.OvertureServiceTargetConfigName) 
     set httpPingServiceRequestObj=##class(IHC.ITF.ITFCOMMON.Request.OvertureService).%New() 
     set httpPingServiceRequestObj.accessToken = token
     set httpPingServiceRequestObj.msgType = msgType
     set httpPingServiceRequestObj.streamObject = jsonReq
     $$$TRACE(" Calling Overture Service  - BEGIN ")     
     set status = process1.SendRequestSync(process1.OvertureServiceTargetConfigName,httpPingServiceRequestObj,.overtureServiceResponse)
     $$$TRACE(" Calling Overture Service  - END ")
     if (status=$$$OK){
	    $$$TRACE("Call Overture service ..Operation OK status.")      
        set overtureServiceResponseData=overtureServiceResponse.Stream  
        $$$TRACE( " overtureServiceResponseData : "_overtureServiceResponseData)
        set statusCode = overtureServiceResponse.Attributes.GetAt("StatusCode")       
        $$$TRACE( " statusCode : "_statusCode)
        set stream =   overtureServiceResponseData
       	set respData = ""
       	While 'stream.AtEnd { 
       		set respData = respData _ stream.ReadLine(,.sc,.eol)       		
       	}
        $$$TRACE(" httpStatusCode: "_statusCode)    

       // set respdata = respData _ " JSON Request: "_jsonProcessRequest.StringValue_$CHAR(10)

        if (statusCode'="200"){
	    	if (statusCode="401"){
		   		$$$TRACE("  CheckError... ")
		   		set status=##class(IHC.ITF.ITFCOMMON.Utility).RetryCheckError(process1.%ConfigName,"Http Status code: ["_statusCode_"]. Invalid access token. Response: ["_respData_"]. Retrying...") 
		   	}elseif (statusCode="400"){
		    	$$$TRACE("  In Status Code 400... ")
		    	$$$TRACE(" respData "_respData)
		    	set status=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(process1.%ConfigName,"Http Status code: ["_statusCode_"]. Invalid/Bad request.   Response: "_respData)
   		    }elseif (statusCode [ "5"){
			    $$$TRACE("  HTTP status codes starting 5.. ")
		   		set status=##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(process1.%ConfigName,"Http Status code: ["_statusCode_"]. Response: ["_respData_"].") 
		    }else{
		    	$$$TRACE("  DisableMsgError.... ")
        		set status=##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(process1.%ConfigName," Response from Overture Service Post Operation: "_respData) 
		    }
		} else {
        		$$$TRACE("Overture Service call status 200 OK !!! ")
        		Do ##class(IHC.ITF.ITFCOMMON.Utility).ResetError(process1.%ConfigName) 

        		set respJSONstring = respData          		
          		$$$TRACE(" respData "_respData)

        } 
    }else{
	    set errTxt = $SYSTEM.Status.GetOneErrorText(status)
	    $$$TRACE("Call Overture Service ERR TEXT: "_errTxt)

    } 

	      quit status
